1205	\begin{proof}
1206	Consider a single input $\mathbf{x}$ with backbone $\mathbf{h} = A\mathbf{x}$, router $p = \sigma(\mathbf{w}^\top\mathbf{h})$, and loss $\ell = p\,\ell_1(\mathbf{h}) + (1-p)\,\ell_2(\mathbf{h})$.
1207	
1208	\emph{Part (i): Unfrozen backbone.} The gradient with respect to $A$ is:
1209	\begin{equation*}
1210	\frac{\partial\ell}{\partial A} = p\,\frac{\partial\ell_1}{\partial\mathbf{h}}\mathbf{x}^\top + (1{-}p)\,\frac{\partial\ell_2}{\partial\mathbf{h}}\mathbf{x}^\top + (\ell_1 - \ell_2)\,p(1{-}p)\,\mathbf{w}\mathbf{x}^\top
1211	\end{equation*}
1212	Under gradient descent $\dot{A} = -\eta\,\partial\ell/\partial A$, the induced change in expert~1's loss is:
1213	\begin{multline*}
1214	\dot{\ell}_1\big|_A = -\eta\|\mathbf{x}\|^2\!\Bigg[p\left\|\frac{\partial\ell_1}{\partial\mathbf{h}}\right\|^2 + (1{-}p)\left(\frac{\partial\ell_1}{\partial\mathbf{h}}\right)^{\!\top}\frac{\partial\ell_2}{\partial\mathbf{h}} \\
1215	 + (\ell_1{-}\ell_2)\,p(1{-}p)\left(\frac{\partial\ell_1}{\partial\mathbf{h}}\right)^{\!\top}\mathbf{w}\Bigg]
1216	\end{multline*}
